#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_STACK 64

static long stack_arr[MAX_STACK];
static int top = 0;

int main(int argc, char **argv) {
    if (argc < 2) {
        puts("ERROR");
        return 0;
    }
    for (int i = 1; i < argc; ++i) {
        char *arg = argv[i];
        /* check if arg is a single-character operator */
        if (strlen(arg) == 1 && strchr("+-*/", arg[0])) {
            if (top < 2) {
                puts("ERROR");
                return 0;
            }
            long b = stack_arr[--top];
            long a = stack_arr[--top];
            long res = 0;
            switch (arg[0]) {
                case '+':
                    res = a + b;
                    break;
                case '-':
                    res = a - b;
                    break;
                case '*':
                    res = a * b;
                    break;
                case '/':
                    if (b == 0) {
                        puts("ERROR");
                        return 0;
                    }
                    res = a / b;
                    break;
                default:
                    puts("ERROR");
                    return 0;
            }
            if (top >= MAX_STACK) {
                puts("ERROR");
                return 0;
            }
            stack_arr[top++] = res;
        } else {
            char *endptr;
            long val = strtol(arg, &endptr, 10);
            if (endptr == arg || *endptr != '\0') {
                puts("ERROR");
                return 0;
            }
            if (top >= MAX_STACK) {
                puts("ERROR");
                return 0;
            }
            stack_arr[top++] = val;
        }
    }
    if (top != 1) {
        puts("ERROR");
        return 0;
    }
    printf("%ld\n", stack_arr[0]);
    return 0;
}
